const readStorage = <T,>(key: string, fallback: T): T => {
  try { return JSON.parse(localStorage.getItem(key) || '') as T; } catch { return fallback; }
};

type ShopContextValue = {
  cart: CartLine[]; wishlist: string[]; addToCart: (p: Product, size: string, blouse: boolean, gift: boolean, qty?: number) => void;
  updateQty: (id: string, delta: number) => void; removeLine: (id: string) => void; toggleWish: (id: string) => void;
  isWished: (id: string) => boolean; cartCount: number;
};
const ShopContext = createContext<ShopContextValue | null>(null);
const useShop = () => useContext(ShopContext) as ShopContextValue;

function ShopProvider({ children }: { children: ReactNode }) {
  const [cart, setCart] = useState<CartLine[]>(() => readStorage('thenmozhi-cart', []));
  const [wishlist, setWishlist] = useState<string[]>(() => readStorage('thenmozhi-wishlist', []));
  useEffect(() => localStorage.setItem('thenmozhi-cart', JSON.stringify(cart)), [cart]);
  useEffect(() => localStorage.setItem('thenmozhi-wishlist', JSON.stringify(wishlist)), [wishlist]);
  const addToCart = (product: Product, size: string, blouse: boolean, gift: boolean, qty = 1) => {
    setCart((lines) => {
      const lineId = `${product.id}-${size}-${blouse}-${gift}`;
      const found = lines.find((line) => line.lineId === lineId);
      return found ? lines.map((line) => line.lineId === lineId ? { ...line, qty: line.qty + qty } : line) : [...lines, { lineId, product, size, blouse, gift, qty }];
    });
  };
  const updateQty = (id: string, delta: number) => setCart((lines) => lines.map((line) => line.lineId === id ? { ...line, qty: Math.max(1, line.qty + delta) } : line));
  const removeLine = (id: string) => setCart((lines) => lines.filter((line) => line.lineId !== id));
  const toggleWish = (id: string) => setWishlist((items) => items.includes(id) ? items.filter((item) => item !== id) : [...items, id]);
  return <ShopContext.Provider value={{ cart, wishlist, addToCart, updateQty, removeLine, toggleWish, isWished: (id) => wishlist.includes(id), cartCount: cart.reduce((sum, line) => sum + line.qty, 0) }}>{children}</ShopContext.Provider>;
}

function Announcement() {
  const messages = ['Chennai customers can avail next day dispatch for customised blouses', 'Free domestic delivery on orders above ₹2,500', 'Handloom, thoughtfully chosen — from our Chennai atelier'];
  const [index, setIndex] = useState(0);
  useEffect(() => { const timer = window.setInterval(() => setIndex((i) => (i + 1) % messages.length), 5000); return () => window.clearInterval(timer); }, []);
  return <div className="bg-[#68045b] px-4 py-2 text-center text-[10px] tracking-[.18em] text-[#fff9ec]"><span className="hidden sm:inline">‹</span><span className="mx-6">{messages[index]}</span><button className="underline underline-offset-4" data-testid="button-announcement-more">Learn more</button><span className="hidden sm:inline ml-6">›</span></div>;
}

