    <div className={`image-zoom group relative overflow-hidden bg-[#f0e5d4] ${list ? 'h-40 w-32 shrink-0' : 'aspect-[.78] w-full'}`}><Link href={`/products/${product.slug}`} className="block h-full w-full" data-testid={`link-product-${product.id}`}><img src={product.image} alt={product.name} className="h-full w-full object-cover object-center" /></Link>{product.tag && <span className="absolute left-3 top-3 bg-[#68045b] px-2 py-1 text-[9px] tracking-caps text-white">{product.tag}</span>}<button onClick={() => toggleWish(product.id)} className="absolute right-3 top-3 flex h-8 w-8 items-center justify-center rounded-full bg-[#fffaf0]/85 text-[#68045b]" aria-label={isWished(product.id) ? `Remove ${product.name} from wishlist` : `Add ${product.name} to wishlist`} data-testid={`button-wishlist-${product.id}`}><Heart size={15} fill={isWished(product.id) ? 'currentColor' : 'none'} /></button><Link href={`/products/${product.slug}`} className="absolute bottom-3 left-3 right-3 hidden bg-[#fffaf0]/95 py-3 text-center text-[10px] tracking-caps text-[#68045b] group-hover:block" data-testid={`link-quick-view-${product.id}`}>View piece</Link></div>
